.copy-btn {
  margin-top: 14px; width: 100%; display: inline-flex; align-items: center; justify-content: center; gap: 7px;
  font: inherit; font-size: 12.5px; font-weight: 700; cursor: pointer;
  color: var(--c); background: var(--panel-2); border: 1px solid var(--border); border-radius: 10px; padding: 9px 12px;
  transition: .15s; -webkit-font-smoothing: antialiased;
